-- PostgreSQL: DDL de dominio gerado das models. Para executar o sistema use manage.py migrate.
BEGIN;
CREATE TABLE "core_cliente" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "contato" varchar(120) NOT NULL);
CREATE TABLE "core_mesa" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "numero" smallint NOT NULL UNIQUE CHECK ("numero" >= 0));
CREATE TABLE "core_cargo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "codigo" varchar(20) NOT NULL UNIQUE);
CREATE TABLE "core_funcionario" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "contato" varchar(120) NOT NULL, "ativo" boolean NOT NULL);
CREATE TABLE "core_exerciciocargo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "funcionario_id" bigint NOT NULL, "cargo_id" bigint NOT NULL, "inicio" timestamp with time zone NOT NULL, "fim" timestamp with time zone NULL, CONSTRAINT "periodo_cargo_valido" CHECK (("fim" IS NULL OR "fim" > ("inicio"))), CONSTRAINT "exercicio_unico" UNIQUE ("funcionario_id", "cargo_id", "inicio"));
CREATE TABLE "core_fornecedor" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "contato" varchar(120) NOT NULL);
CREATE TABLE "core_ingrediente" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "unidade" varchar(3) NOT NULL, "estoque" numeric(12, 3) NOT NULL, "fornecedor_id" bigint NOT NULL, CONSTRAINT "estoque_nao_negativo" CHECK ("estoque" >= 0));
CREATE TABLE "core_categoria" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL);
CREATE TABLE "core_produto" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "categoria_id" bigint NOT NULL, "preco_base" numeric(10, 2) NOT NULL, "combo" boolean NOT NULL, "ativo" boolean NOT NULL, CONSTRAINT "preco_produto_valido" CHECK ("preco_base" >= 0));
CREATE TABLE "core_receita" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "produto_id" bigint NOT NULL, "ingrediente_id" bigint NOT NULL, "quantidade" numeric(12, 3) NOT NULL, CONSTRAINT "receita_unica" UNIQUE ("produto_id", "ingrediente_id"), CONSTRAINT "receita_qtd_positiva" CHECK ("quantidade" > 0));
CREATE TABLE "core_componentecombo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "combo_id" bigint NOT NULL, "produto_id" bigint NOT NULL, "quantidade" smallint NOT NULL CHECK ("quantidade" >= 0), CONSTRAINT "componente_unico" UNIQUE ("combo_id", "produto_id"), CONSTRAINT "combo_sem_autorreferencia" CHECK (NOT ("combo_id" = ("produto_id"))), CONSTRAINT "componente_qtd_positiva" CHECK ("quantidade" > 0));
CREATE TABLE "core_variacao" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "produto_id" bigint NOT NULL, "grupo" varchar(60) NOT NULL, "acrescimo" numeric(10, 2) NOT NULL, CONSTRAINT "variacao_unica" UNIQUE ("produto_id", "grupo", "nome"), CONSTRAINT "variacao_preco_valido" CHECK ("acrescimo" >= 0));
CREATE TABLE "core_adicional" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "preco" numeric(10, 2) NOT NULL, CONSTRAINT "adicional_preco_valido" CHECK ("preco" >= 0));
CREATE TABLE "core_produtoadicional" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "produto_id" bigint NOT NULL, "adicional_id" bigint NOT NULL, CONSTRAINT "adicional_permitido_unico" UNIQUE ("produto_id", "adicional_id"));
CREATE TABLE "core_receitaadicional" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "adicional_id" bigint NOT NULL, "ingrediente_id" bigint NOT NULL, "quantidade" numeric(12, 3) NOT NULL, CONSTRAINT "receita_adicional_unica" UNIQUE ("adicional_id", "ingrediente_id"), CONSTRAINT "receita_adicional_qtd" CHECK ("quantidade" > 0));
CREATE TABLE "core_promocao" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL, "inicio" timestamp with time zone NOT NULL, "fim" timestamp with time zone NOT NULL, CONSTRAINT "periodo_promocao_valido" CHECK ("fim" > ("inicio")));
CREATE TABLE "core_promocaoproduto" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "promocao_id" bigint NOT NULL, "produto_id" bigint NOT NULL, "preco" numeric(10, 2) NOT NULL, CONSTRAINT "promocao_produto_unico" UNIQUE ("promocao_id", "produto_id"), CONSTRAINT "promocao_preco_valido" CHECK ("preco" >= 0));
CREATE TABLE "core_cupom" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "codigo" varchar(30) NOT NULL UNIQUE, "tipo" varchar(10) NOT NULL, "valor" numeric(10, 2) NOT NULL, "inicio" timestamp with time zone NOT NULL, "fim" timestamp with time zone NOT NULL, CONSTRAINT "cupom_periodo_valido" CHECK ("fim" > ("inicio")), CONSTRAINT "cupom_valor_valido" CHECK (("valor" > 0 AND ("tipo" = 'VALOR' OR ("tipo" = 'PERCENTUAL' AND "valor" <= 100)))));
CREATE TABLE "core_pedido" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "cliente_id" bigint NULL, "atendente_id" bigint NOT NULL, "mesa_id" bigint NULL, "canal" varchar(10) NOT NULL, "modalidade" varchar(10) NOT NULL, "criado_em" timestamp with time zone NOT NULL, "desconto" numeric(10, 2) NOT NULL, CONSTRAINT "pedido_mesa_modalidade" CHECK ((("mesa_id" IS NOT NULL AND "modalidade" = 'LOCAL') OR ("mesa_id" IS NULL AND "modalidade" IN ('RETIRADA', 'DELIVERY')))), CONSTRAINT "pedido_cliente_obrigatorio" CHECK (("cliente_id" IS NOT NULL OR (NOT ("canal" = 'APP') AND NOT ("modalidade" = 'DELIVERY')))), CONSTRAINT "pedido_desconto_valido" CHECK ("desconto" >= 0), CONSTRAINT "pedido_canal_valido" CHECK ("canal" IN ('BALCAO', 'TELEFONE', 'APP')));
CREATE TABLE "core_itempedido" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pedido_id" bigint NOT NULL, "produto_id" bigint NOT NULL, "quantidade" smallint NOT NULL CHECK ("quantidade" >= 0), "preco_base" numeric(10, 2) NOT NULL, "promocao_id" bigint NULL, "observacao" varchar(300) NOT NULL, CONSTRAINT "item_quantidade_positiva" CHECK ("quantidade" > 0), CONSTRAINT "item_preco_valido" CHECK ("preco_base" >= 0));
CREATE TABLE "core_itemvariacao" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "item_id" bigint NOT NULL, "variacao_id" bigint NOT NULL, "acrescimo" numeric(10, 2) NOT NULL, CONSTRAINT "item_variacao_unica" UNIQUE ("item_id", "variacao_id"), CONSTRAINT "item_variacao_preco" CHECK ("acrescimo" >= 0));
CREATE TABLE "core_itemadicional" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "item_id" bigint NOT NULL, "adicional_id" bigint NOT NULL, "quantidade" smallint NOT NULL CHECK ("quantidade" >= 0), "preco" numeric(10, 2) NOT NULL, CONSTRAINT "item_adicional_unico" UNIQUE ("item_id", "adicional_id"), CONSTRAINT "item_adicional_qtd" CHECK ("quantidade" > 0), CONSTRAINT "item_adicional_preco" CHECK ("preco" >= 0));
CREATE TABLE "core_consumoitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "item_id" bigint NOT NULL, "ingrediente_id" bigint NOT NULL, "quantidade" numeric(12, 3) NOT NULL, CONSTRAINT "consumo_item_unico" UNIQUE ("item_id", "ingrediente_id"), CONSTRAINT "consumo_item_qtd" CHECK ("quantidade" > 0));
CREATE TABLE "core_formapagamento" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nome" varchar(120) NOT NULL);
CREATE TABLE "core_pagamento" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pedido_id" bigint NOT NULL, "forma_id" bigint NOT NULL, "valor" numeric(10, 2) NOT NULL, CONSTRAINT "pagamento_positivo" CHECK ("valor" > 0), CONSTRAINT "pagamento_forma_unica" UNIQUE ("pedido_id", "forma_id"));
CREATE TABLE "core_historicostatus" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pedido_id" bigint NOT NULL, "status" varchar(15) NOT NULL, "ocorrido_em" timestamp with time zone NOT NULL, CONSTRAINT "historico_status_valido" CHECK ("status" IN ('RECEBIDO', 'EM_PREPARO', 'PRONTO', 'SAIU_ENTREGA', 'CONCLUIDO', 'CANCELADO')));
CREATE TABLE "core_usocupom" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pedido_id" bigint NOT NULL UNIQUE, "cupom_id" bigint NOT NULL, "cliente_id" bigint NOT NULL, CONSTRAINT "cupom_uma_vez_cliente" UNIQUE ("cupom_id", "cliente_id"));
CREATE TABLE "core_entrega" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pedido_id" bigint NOT NULL UNIQUE, "entregador_id" bigint NOT NULL, "logradouro" varchar(150) NOT NULL, "numero" varchar(15) NOT NULL, "complemento" varchar(100) NOT NULL, "bairro" varchar(80) NOT NULL, "cidade" varchar(80) NOT NULL, "cep" varchar(9) NOT NULL, "distancia_km" numeric(6, 2) NOT NULL, "taxa" numeric(10, 2) NOT NULL, CONSTRAINT "entrega_valores_validos" CHECK (("distancia_km" >= 0 AND "taxa" >= 0)));
CREATE TABLE "core_avaliacao" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pedido_id" bigint NOT NULL UNIQUE, "nota" smallint NOT NULL CHECK ("nota" >= 0), "comentario" varchar(500) NOT NULL, CONSTRAINT "avaliacao_nota_valida" CHECK (("nota" >= 1 AND "nota" <= 5)));
